 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>
   <main id="main-content" tabindex="-1">
     <section class="card" aria-labelledby="page-title">
       <p class="eyebrow">Preferences</p>
       <h1 id="page-title">Choose your notification channel</h1>
       <p class="intro">Tell us how you prefer to receive updates so we can send messages in the way that works best for you.</p>

       <form id="notification-form" novalidate>
         <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required field</p>

         <div class="form-field">
           <fieldset id="notification-group" aria-describedby="notification-help notification-error">
             <legend>How do you prefer to receive notifications? <span class="required-mark" aria-hidden="true">*</span></legend>
             <p class="help-text" id="notification-help">Choose exactly one option.</p>

             <div class="options">
               <div class="option">
                 <input id="notification-email" type="radio" name="notificationPreference" value="Email" required>
                 <label for="notification-email">Email</label>
               </div>

               <div class="option">
                 <input id="notification-sms" type="radio" name="notificationPreference" value="SMS" required>
                 <label for="notification-sms">SMS</label>
               </div>

               <div class="option">
                 <input id="notification-push" type="radio" name="notificationPreference" value="Push Notifications" required>
                 <label for="notification-push">Push Notifications</label>
               </div>
             </div>

             <p class="error-message" id="notification-error" hidden></p>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Save preference</button>
           <p class="status-message" id="form-status" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const radioButtons = Array.from(form.elements.namedItem("notificationPreference"));
     const errorMessage = document.getElementById("notification-error");
     const statusMessage = document.getElementById("form-status");

     function setGroupInvalid(isInvalid) {
       radioButtons.forEach((radio) => {
         radio.setAttribute("aria-invalid", String(isInvalid));
       });
     }

     function getSelectedValue() {
       const checkedRadio = radioButtons.find((radio) => radio.checked);
       return checkedRadio ? checkedRadio.value : "";
     }

     function clearError() {
       errorMessage.hidden = true;
       errorMessage.textContent = "";
       setGroupInvalid(false);
     }

     radioButtons.forEach((radio) => {
       radio.addEventListener("change", () => {
         clearError();
         statusMessage.textContent = "";
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedValue = getSelectedValue();

       if (!selectedValue) {
         errorMessage.hidden = false;
         errorMessage.textContent = "Error: Select how you prefer to receive notifications.";
         statusMessage.textContent = "";
         setGroupInvalid(true);
         radioButtons[0].focus();
         return;
       }

       clearError();
       statusMessage.textContent = `Preference saved: ${selectedValue}.`;
     });
   </script>
